package vn.svframe.svframemmo.cobblemon.gameplay;
import java.util.*;import java.nio.file.*;import java.math.BigInteger;import com.google.gson.*;import com.cobblemon.mod.common.Cobblemon;import com.cobblemon.mod.common.entity.pokemon.PokemonEntity;import com.cobblemon.mod.common.api.pokemon.PokemonProperties;import com.cobblemon.mod.common.api.pokedex.PokedexManager;import com.cobblemon.mod.common.api.spawning.position.SpawnablePosition;import com.cobblemon.mod.common.api.spawning.detail.*;import net.minecraft.server.MinecraftServer;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.util.math.Vec3d;import net.minecraft.text.Text;import com.mojang.serialization.JsonOps;
/** Native state changes: party/PC outcomes faint Pokemon, never remove stored records. */
public final class CosmicPokemonBridge {
 private static volatile String boostType="";private static volatile long boostEnd;private static volatile double boostFactor=1,rareFactor=3;
 static {try{var file=Path.of("config/svframeworldboss/spawn-boost.json");if(Files.exists(file)){var o=JsonParser.parseString(Files.readString(file)).getAsJsonObject();boostType=o.get("type").getAsString();boostEnd=o.get("until").getAsLong();boostFactor=o.get("factor").getAsDouble();}}catch(Exception ignored){}}
 public static void configure(double multiplier){rareFactor=multiplier;}
 public static void boost(String type,long until,double multiplier){boostType=type;boostEnd=until;boostFactor=multiplier;try{var file=Path.of("config/svframeworldboss/spawn-boost.json");Files.createDirectories(file.getParent());var o=new JsonObject();o.addProperty("type",type);o.addProperty("until",until);o.addProperty("factor",multiplier);Files.writeString(file,o.toString());}catch(Exception e){throw new IllegalStateException("Could not persist spawn boost",e);}}
 public static float weight(SpawnablePosition at,SpawnDetail detail,float weight){if(!(detail instanceof PokemonSpawnDetail p))return weight;double factor=1;var species=p.getPokemon().getSpecies();var nativeSpecies=species==null?null:com.cobblemon.mod.common.api.pokemon.PokemonSpecies.getByName(species);if(nativeSpecies!=null&&System.currentTimeMillis()<boostEnd)for(var type:nativeSpecies.getTypes())if(type.getName().equalsIgnoreCase(boostType)){factor*=boostFactor;break;}
  if(detail.getBucket().contains("rare"))for(var player:at.getWorld().getPlayers())if(player.getChunkPos().x==(at.getPosition().getX()>>4)&&player.getChunkPos().z==(at.getPosition().getZ()>>4)&&player.getCommandTags().contains("svframe_cosmic_reality")){factor*=rareFactor;break;}return (float)Math.min(Float.MAX_VALUE,weight*factor);}
 public static void legendary(ServerPlayerEntity p,String species){var entity=PokemonProperties.Companion.parse(species+" level=80").createEntity(p.getServerWorld());var look=p.getRotationVec(1);var at=p.getPos().add(look.x*4,0,look.z*4);entity.refreshPositionAndAngles(at.x,at.y,at.z,0,0);if(!p.getServerWorld().isSpaceEmpty(entity)){entity.discard();throw new IllegalStateException("Legendary spawn area is blocked");}if(!p.getServerWorld().spawnEntity(entity))throw new IllegalStateException("Legendary spawn rejected");}
 private static void backup(ServerPlayerEntity p,String kind,JsonElement data){try{var path=Path.of("config/svframeworldboss/snap-backups",p.getUuidAsString(),System.currentTimeMillis()+"-"+kind+".json");Files.createDirectories(path.getParent());byte[] bytes=new GsonBuilder().setPrettyPrinting().create().toJson(data).getBytes(java.nio.charset.StandardCharsets.UTF_8);try(var channel=java.nio.channels.FileChannel.open(path,StandardOpenOption.CREATE_NEW,StandardOpenOption.WRITE)){var buffer=java.nio.ByteBuffer.wrap(bytes);while(buffer.hasRemaining())channel.write(buffer);channel.force(true);}}catch(Exception e){throw new IllegalStateException("Backup failed; no destructive changes applied",e);}}
 public static void faintAll(ServerPlayerEntity p){var storage=Cobblemon.INSTANCE.getStorage();var party=storage.getParty(p);var pc=storage.getPC(p);var partyWriter=storeWriter(storage,party);var pcWriter=storeWriter(storage,pc);var snapshot=new JsonObject();snapshot.add("party",party.saveToJSON(new JsonObject(),p.getRegistryManager()));snapshot.add("pc",pc.saveToJSON(new JsonObject(),p.getRegistryManager()));backup(p,"faint-party-pc",snapshot);int count=0;for(var pokemon:party){pokemon.setCurrentHealth(0);count++;}for(var pokemon:pc){pokemon.setCurrentHealth(0);count++;}saveStore(partyWriter,party,p);saveStore(pcWriter,pc,p);p.sendMessage(Text.literal("§5SNAP: "+count+" Pokémon fainted. Party and PC slots preserved."),false);}
 private static com.cobblemon.mod.common.api.storage.factory.FileBackedPokemonStoreFactory<?> storeWriter(com.cobblemon.mod.common.api.storage.PokemonStoreManager manager,com.cobblemon.mod.common.api.storage.PokemonStore<?> store){for(var factory:((vn.svframe.svframemmo.cobblemon.mixin.PokemonStoreAccess)manager).svframe$factories())if(factory instanceof com.cobblemon.mod.common.api.storage.factory.FileBackedPokemonStoreFactory<?> file&&file.isCached(store))return file;throw new IllegalStateException("No supported persistent Pokemon store writer; destructive SNAP refused before mutation");}
 private static void saveStore(com.cobblemon.mod.common.api.storage.factory.FileBackedPokemonStoreFactory<?> file,com.cobblemon.mod.common.api.storage.PokemonStore<?> store,ServerPlayerEntity p){var access=(vn.svframe.svframemmo.cobblemon.mixin.PokemonFileStoreAccess)file;var adapter=access.svframe$adapter();var snapshot=adapter.serialize(store,p.getRegistryManager());try{access.svframe$writer().submit(()->adapter.save((Class)store.getClass(),store.getUuid(),snapshot)).get(30,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception e){throw new IllegalStateException("Native Pokemon storage write failed; SNAP snapshot retained",e);}}
 public static void wipeDexHalf(ServerPlayerEntity p){var dex=Cobblemon.INSTANCE.getPlayerDataManager().getPokedexData(p);var encoded=PokedexManager.Companion.getCODEC().encodeStart(JsonOps.INSTANCE,dex).getOrThrow();backup(p,"pokedex",encoded);var ids=new ArrayList<>(dex.getSpeciesRecords().keySet());Collections.shuffle(ids);int n=ids.size()/2;DexWipeGuard.record(p,new HashSet<>(ids.subList(0,n)));for(var id:ids.subList(0,n))dex.getSpeciesRecords().remove(id);dex.clearCalculatedValues();Cobblemon.INSTANCE.getPlayerDataManager().saveSingle(dex,com.cobblemon.mod.common.api.storage.player.PlayerInstancedDataStoreTypes.INSTANCE.getPOKEDEX());Cobblemon.INSTANCE.getPlayerDataManager().syncAllToPlayer(p);p.sendMessage(Text.literal("§5SNAP: "+n+" Pokédex records erased. Pokémon ownership is unchanged; Pokédex synchronized."),false);}
 public static void dustWildHalf(MinecraftServer server){var list=new ArrayList<PokemonEntity>();for(var world:server.getWorlds())for(var e:world.iterateEntities())if(e instanceof PokemonEntity p&&p.getOwnerUuid()==null&&!p.getPokemon().isNPCOwned()&&!p.isBattling()&&!p.isBusy()&&!p.getCommandTags().contains("svframe_worldboss")&&!p.getCommandTags().contains("svframe_cosmic_minion"))list.add(p);Collections.shuffle(list);for(int i=0;i<list.size()/2;i++){var e=list.get(i);((net.minecraft.server.world.ServerWorld)e.getWorld()).spawnParticles(net.minecraft.particle.ParticleTypes.ASH,e.getX(),e.getY()+.5,e.getZ(),15,.2,.2,.2,.05);e.discard();}}
 public static void money(ServerPlayerEntity p,int amount){
  if(amount<0)throw new IllegalArgumentException("Negative SNAP reward");
  var service=vn.svframe.svframelib.api.economy.CurrencyService.get();var currency=vn.svframe.svframelib.api.economy.CurrencyKey.parse("beconomy:secondary");
  if(!service.isAvailable(currency))throw new IllegalStateException("BEconomy Secondary unavailable; SNAP reward retained for reconciliation");
  service.deposit(p,currency,java.math.BigDecimal.valueOf(amount));
 }
}
